import csv

# Get all molecule_ids that have triple bonds
triple_bond_molecules = {'TR041', 'TR377', 'TR499', 'TR447'}

# Check each triple-bond molecule for P or Br
molecules_with_p_or_br = set()
elements_in_triple_bond_molecules = {}

with open('csv/atom.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        molecule_id = row['molecule_id']
        element = row['element'].lower()

        if molecule_id in triple_bond_molecules:
            if molecule_id not in elements_in_triple_bond_molecules:
                elements_in_triple_bond_molecules[molecule_id] = set()
            elements_in_triple_bond_molecules[molecule_id].add(element)

            if element == 'p' or element == 'br':
                molecules_with_p_or_br.add(molecule_id)

print("Elements in each triple-bond molecule:")
for mol, elems in sorted(elements_in_triple_bond_molecules.items()):
    print(f"  {mol}: {sorted(elems)}")

print(f"\nMolecules with triple bonds containing P or Br: {molecules_with_p_or_br}")

